import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Build a minimum shared-cost directed broadcast tree for small fan-outs.

    A directed Steiner dynamic program merges receiver subsets at relays before
    propagating them upstream, so a cloud-egress edge used by multiple receivers
    is paid once.  Large requests use deterministic greedy shared-edge routes.
    """
    import heapq

    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    h.remove_edges_from([
        (u, v) for u, v, data in h.edges(data=True)
        if data.get("cost") is None
    ])

    terminals = [d for d in dict.fromkeys(dsts) if d != src]
    if not terminals:
        return BroadCastTopology(src, dsts, num_partitions)
    for dst in terminals:
        if not nx.has_path(h, src, dst):
            raise nx.NetworkXNoPath(
                "No priced broadcast route from %s to %s" % (src, dst)
            )

    def emit(routes):
        """Populate every destination/partition with its source-to-leaf route."""
        topology = BroadCastTopology(src, dsts, num_partitions)
        for dst in dsts:
            if dst == src:
                continue
            for u, v in zip(routes[dst], routes[dst][1:]):
                edge = [u, v, G[u][v]]
                for partition in range(num_partitions):
                    topology.append_dst_partition_path(dst, partition, edge)
        return topology

    # The subset DP is still inexpensive for ten cloud destinations on the
    # relatively small region graphs used here, and avoids greedy ordering
    # artifacts for medium-sized broadcast requests.
    if len(terminals) <= 10:
        nodes = list(h)
        incoming = {
            node: [(parent, float(h[parent][node]["cost"]))
                   for parent in h.predecessors(node)]
            for node in nodes
        }
        dp, choice = {}, {}

        for mask in range(1, 1 << len(terminals)):
            cost = {node: float("inf") for node in nodes}
            decision, heap, serial = {}, [], 0

            if mask & (mask - 1) == 0:
                terminal = terminals[mask.bit_length() - 1]
                cost[terminal] = 0.0
                decision[terminal] = ("terminal",)
                heapq.heappush(heap, (0.0, serial, terminal))
                serial += 1
            else:
                subset = (mask - 1) & mask
                while subset:
                    other = mask ^ subset
                    if other and subset < other:
                        for node in nodes:
                            value = dp[subset][node] + dp[other][node]
                            if value < cost[node]:
                                cost[node] = value
                                decision[node] = ("merge", subset, other)
                    subset = (subset - 1) & mask
                for node in nodes:
                    if cost[node] < float("inf"):
                        heapq.heappush(heap, (cost[node], serial, node))
                        serial += 1

            while heap:
                value, _, node = heapq.heappop(heap)
                if value != cost[node]:
                    continue
                for parent, edge_cost in incoming[node]:
                    candidate = value + edge_cost
                    if candidate + 1e-12 < cost[parent]:
                        cost[parent] = candidate
                        decision[parent] = ("step", node)
                        heapq.heappush(heap, (candidate, serial, parent))
                        serial += 1
            dp[mask], choice[mask] = cost, decision

        edges = set()

        def collect(mask, node):
            """Recover selected edges from the subset-DP decisions."""
            action = choice[mask][node]
            if action[0] == "step":
                edges.add((node, action[1]))
                collect(mask, action[1])
            elif action[0] == "merge":
                collect(action[1], node)
                collect(action[2], node)

        collect((1 << len(terminals)) - 1, src)
        tree = nx.DiGraph()
        tree.add_edges_from(edges)
        return emit({
            dst: nx.shortest_path(tree, src, dst)
            for dst in terminals
        })

    def build(order):
        """Insert routes with zero incremental price for already-paid edges."""
        routes, used = {}, set()
        for dst in order:
            path = nx.shortest_path(
                h, src, dst,
                weight=lambda u, v, data:
                    0.0 if (u, v) in used else float(data["cost"])
            )
            routes[dst] = path
            used.update(zip(path, path[1:]))
        return routes

    def cost(routes):
        """Compute the unique priced-edge cost of a candidate tree."""
        return sum(
            float(h[u][v]["cost"])
            for u, v in {
                edge
                for path in routes.values()
                for edge in zip(path, path[1:])
            }
        )

    def adaptive_build(first):
        """Grow a tree by repeatedly attaching the least-cost new receiver.

        Already selected edges have zero marginal price while evaluating each
        candidate path.  Trying every possible initial receiver avoids making
        the greedy result depend on the caller's destination ordering.
        """
        routes, used = {}, set()
        remaining = set(terminals)

        while remaining:
            candidates = []
            for dst in remaining:
                path = nx.shortest_path(
                    h, src, dst,
                    weight=lambda u, v, data:
                        0.0 if (u, v) in used else float(data["cost"])
                )
                marginal = sum(
                    float(h[u][v]["cost"])
                    for u, v in zip(path, path[1:])
                    if (u, v) not in used
                )
                # Enforce the requested seed only for the first attachment.
                seed_penalty = 0 if not routes and dst == first else 1
                candidates.append(
                    (seed_penalty, marginal, terminals.index(dst), dst, path)
                )

            _, _, _, dst, path = min(candidates)
            routes[dst] = path
            used.update(zip(path, path[1:]))
            remaining.remove(dst)

        return routes

    orders = []
    for sequence in (terminals, list(reversed(terminals))):
        for i in range(len(sequence)):
            orders.append(sequence[i:] + sequence[:i])

    candidates = [build(order) for order in orders]
    candidates.extend(adaptive_build(dst) for dst in terminals)
    return emit(min(candidates, key=cost))


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


# EVOLVE-BLOCK-END

# Helper functions that won't be evolved
def create_broadcast_topology(src: str, dsts: List[str], num_partitions: int = 4):
    """Create a broadcast topology instance"""
    return BroadCastTopology(src, dsts, num_partitions)

def run_search_algorithm(src: str, dsts: List[str], G, num_partitions: int):
    """Run the search algorithm and return the topology"""
    return search_algorithm(src, dsts, G, num_partitions)

